/**
 * KNOWN-ANSWER QR MATRICES FROM AN INDEPENDENT ENCODER.
 *
 * Generated ONCE from `toqr@0.1.1` (Phil Pluckthun, MIT — in this workspace transitively
 * via the mobile prototype, never a webapp dependency) at error-correction level M, then
 * frozen here. The point is independence: `test/qr.test.ts` builds its decoder from the
 * spec, and a decoder that reads THESE matrices back to their exact source strings cannot
 * merely share `app/shell/qr.ts`'s misconceptions — it has been checked against bytes this
 * repository's encoder had no hand in. `v8txt` is version SEVEN, deliberately: versions >= 7
 * carry the 18-bit version-information blocks, which no smaller code exercises.
 *
 * Regeneration (should the strings ever change):
 *   node -e "const {toQR}=require('toqr'); const o=toQR(text, 0); …one char per module, row-major"
 */
export interface KnownQr { text: string; size: number; rows: string[] }

